package api

import (
	"net/http/httptest"
	"testing"
)

func TestHelloIntegration(t *testing.T) {
	rec := httptest.NewRecorder()
	Hello(rec, httptest.NewRequest("GET", "/?name=a", nil))
	if got := rec.Body.String(); got != "hello a" {
		t.Fatalf("body %q", got)
	}
}
